ri = lambda : int(input())
rl = lambda : list(map(int, input().split()))
rs = lambda : input()
from collections import defaultdict
import sys
sys.setrecursionlimit(100000)
t = ri()
for test in range(t):
	s = rs()
	p = list(rs())
	arr = [[0, chr(i + 97)] for i in range(26)]
	for i in p:
		i = i.lower()
		if ord(i) < 97 or ord(i) > 122:
			continue
		arr[ord(i) - ord('a')][0] += 1
	arr.sort()
	d = {}
	for i in range(26):
		d[arr[i][1]] = s[i]
	ans = ''
	for i in p:
		if i.lower() in d:
			if i.islower():
				ans += d[i]
			else:
				ans += d[i.lower()].upper()
		else:
			ans += i
	print(ans)
